<?php
namespace Xdecaro\Component\Decaroevents\Administrator\Model; defined('_JEXEC') or die; use Joomla\CMS\Factory; use Joomla\CMS\MVC\Model\ListModel;
final class SessionsModel extends ListModel { protected function populateState($ordering='s.start_at',$direction='ASC'){parent::populateState($ordering,$direction);$this->setState('filter.search',Factory::getApplication()->input->getString('filter_search'));} protected function getListQuery(){ $db=$this->getDatabase();$q=$db->getQuery(true)->select('s.*, e.title AS event_title')->from($db->quoteName('#__decaroevents_sessions','s'))->join('INNER',$db->quoteName('#__decaroevents_events','e').' ON e.id=s.event_id');$s=trim((string)$this->getState('filter.search'));if($s!==''){$like=$db->quote('%'.$db->escape($s,true).'%');$q->where('('.$db->quoteName('s.title').' LIKE '.$like.' OR '.$db->quoteName('e.title').' LIKE '.$like.')');}$q->order('s.start_at ASC');return $q;} }
